fn rjust(orig: Vec<char>, width: u8, fillchar: char) -> Vec<char> {
    let orig_len = orig.len();
    let target = width as usize;
    if orig_len >= target {
        // Original sequence is already as long or longer than target width
        orig
    } else {
        // Need to pad with fillchar at the front
        let mut result = Vec::with_capacity(target);
        let pad_len = target - orig_len;
        result.extend(std::iter::repeat(fillchar).take(pad_len));
        result.extend(orig.into_iter());
        result
    }
}